DROP VIEW IF EXISTS vw_claims_enriched;
CREATE VIEW vw_claims_enriched AS
SELECT c.Claim_ID,c.Patient_ID,c.Service_Date,c.Submission_Date,CAST(julianday(c.Submission_Date)-julianday(c.Service_Date) AS INTEGER) Submission_Lag_Days,COALESCE(c.Provider_ID,'Unknown') Provider_ID,COALESCE(pv.Provider_Display_Name,'Unknown') Provider_Display_Name,pv.Specialty,c.Facility_ID,f.Facility_Name,f.Facility_Type,f.Facility_Size,c.Payer,c.Claim_Type,c.Claim_Status,c.Diagnosis_Code,dc.Diagnosis_Name,dc.Clinical_Group,c.Primary_Procedure_Code,pc.Procedure_Name,pc.Procedure_Group,c.Claim_Amount,c.Allowed_Amount,c.Paid_Amount,c.Member_Responsibility,ROUND(c.Claim_Amount-c.Allowed_Amount,2) Contractual_Adjustment,ROUND(c.Allowed_Amount-c.Paid_Amount,2) Unpaid_Allowed_Amount,p.Age,p.Gender,p.Region Patient_Region,CASE WHEN c.Paid_Amount>c.Allowed_Amount THEN 1 ELSE 0 END Financial_Exception_Flag
FROM claims c LEFT JOIN patients p ON c.Patient_ID=p.Patient_ID LEFT JOIN providers pv ON c.Provider_ID=pv.Provider_ID LEFT JOIN facilities f ON c.Facility_ID=f.Facility_ID LEFT JOIN diagnosis_catalog dc ON c.Diagnosis_Code=dc.Diagnosis_Code LEFT JOIN procedure_catalog pc ON c.Primary_Procedure_Code=pc.Procedure_Code;
